            int front = 0, back = 0;
            color[start] = 0;
            queue[back++] = start;

            while (front < back) {
                int u = queue[front++];
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (color[v] == -1) {
                        color[v] = (byte) (1 - color[u]);
                        queue[back++] = v;
                    }
                }
            }
        }

        StringBuilder team1 = new StringBuilder();
        StringBuilder team2 = new StringBuilder();

        for (int i = 1; i <= n; i++) {
            if (color[i] == 0) {
